#include <stdlib.h>
int** zigzagLevelOrder(struct TreeNode*r,int*rs,int**rc){if(!r){*rs=0;*rc=NULL;return NULL;}struct TreeNode**q=malloc(2048*sizeof(*q));int h=0,t=0,lvl=0;q[t++]=r;int**o=malloc(2048*sizeof(int*)),*c=malloc(2048*sizeof(int));while(h<t){int n=t-h;int*v=malloc(n*sizeof(int));for(int i=0;i<n;i++){struct TreeNode*x=q[h++];v[(lvl&1)?n-1-i:i]=x->val;if(x->left)q[t++]=x->left;if(x->right)q[t++]=x->right;}o[lvl]=v;c[lvl++]=n;}free(q);*rs=lvl;*rc=c;return o;}
